\set ON_ERROR_STOP on
\o /dev/null
begin;
select set_config('app.audit_reason','Fixtures isoladas de entrega e impressao',true);
create function pg_temp.assert(ok boolean,msg text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',msg;end if;end $$;
grant execute on function pg_temp.assert(boolean,text) to anon,authenticated,service_role;
insert into auth.users(id) values('e0000000-0000-0000-0000-000000000001'),('e0000000-0000-0000-0000-000000000002');
update public.profiles set role='admin',active=true where id='e0000000-0000-0000-0000-000000000001';
update public.profiles set role='cashier',active=true where id='e0000000-0000-0000-0000-000000000002';
insert into public.terminals(id,name) values('e1000000-0000-0000-0000-000000000001','Terminal entrega teste');
insert into app_private.terminal_leases(user_id,session_id,expires_at,terminal_id) values('e0000000-0000-0000-0000-000000000002','delivery-test',now()+interval '10 minutes','e1000000-0000-0000-0000-000000000001');
insert into public.products(id,name,category,price_cents,sector) values('test-delivery-burger','Burger entrega','hamburgueres',1000,'grill');
insert into public.ingredients(id,name,unit,stock,unit_cost_cents) values('e2000000-0000-0000-0000-000000000001','Insumo entrega','un',100,100);
insert into public.recipe_items values('test-delivery-burger','e2000000-0000-0000-0000-000000000001',1);
update public.online_shop_settings set enabled=true,delivery_enabled=true,delivery_fee_cents=100,delivery_card_enabled=true;
select set_config('test.delivery_items','[{"product_id":"test-delivery-burger","quantity":1,"price_cents":1}]',true);
select set_config('test.delivery_contact','{"name":"Cliente reservado","phone":"5581999999999","email":"fixture@example.test","address":"Rua da entrega 123, Centro","reference":"Ao lado da farmacia","whatsapp_consent":true}',true);
select pg_temp.assert(app_private.delivery_card_fee(25)=2 and app_private.delivery_card_fee(8)=0 and app_private.delivery_card_fee(1005)=60,'6% arredondados uma vez, em centavos, sem ponto flutuante');
select pg_temp.assert(not has_function_privilege('anon','public.online_print_claim(text)','execute') and not has_function_privilege('authenticated','public.online_print_claim(text)','execute'),'clientes e equipe nao retiram cupons diretamente');
select pg_temp.assert(not has_function_privilege('anon','public.online_register_printer(text,text)','execute'),'visitante nao cadastra agente');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert((public.online_delivery_quote(current_setting('test.delivery_items')::jsonb,'delivery','card_delivery')->>'total_cents')::int=1166,'6% sobre produtos + entrega com preco canonico');
select pg_temp.assert((public.online_delivery_quote(current_setting('test.delivery_items')::jsonb,'delivery','cash')->>'total_cents')::int=1100,'dinheiro nao recebe acrescimo');
do $$begin
 begin perform public.online_delivery_quote(current_setting('test.delivery_items')::jsonb,'pickup','card_delivery');raise exception 'ASSERT: cartao na entrega para retirada';exception when raise_exception then if sqlerrm<>'payment_unavailable' then raise;end if;end;
 begin perform public.online_create_order(gen_random_uuid(),repeat('1',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb,'delivery','card_delivery',null,1100);raise exception 'ASSERT: cliente suprimiu taxa';exception when raise_exception then if sqlerrm<>'price_changed_review_order' then raise;end if;end;
 begin perform public.online_create_order(gen_random_uuid(),repeat('2',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb-'reference','delivery','cash',null,1100);raise exception 'ASSERT: entrega sem referencia';exception when raise_exception then if sqlerrm<>'delivery_reference_required' then raise;end if;end;
 begin perform public.online_create_order(gen_random_uuid(),repeat('3',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb,'delivery','cash',1000,1100);raise exception 'ASSERT: troco menor que total';exception when raise_exception then if sqlerrm<>'invalid_change_amount' then raise;end if;end;
end $$;
select set_config('test.delivery_card',(public.online_create_order('e3000000-0000-0000-0000-000000000001',repeat('4',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb,'delivery','card_delivery',null,1166)->>'id'),true);
select public.online_create_order('e3000000-0000-0000-0000-000000000001',repeat('4',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb,'delivery','card_delivery',null,1166);
select pg_temp.assert((public.online_order_status(repeat('4',64))->>'due_cents')::int=1166 and public.online_order_status(repeat('4',64))->>'status'='accepted','preparo imediato nao confirma recebimento');
select pg_temp.assert(position('Cliente reservado' in public.online_order_status(repeat('4',64))::text)=0 and position(repeat('4',64) in public.online_order_status(repeat('4',64))::text)=0,'acompanhamento nao revela contatos nem segredo');
select pg_temp.assert(jsonb_array_length(public.online_order_status(repeat('4',64))->'history')=2,'historico registra criacao e entrada na cozinha');
reset role;
select pg_temp.assert((select stock=99 from public.ingredients where id='e2000000-0000-0000-0000-000000000001'),'retry nao duplica baixa de estoque');
select pg_temp.assert((select count(*)=1 from app_private.online_print_jobs where order_id=current_setting('test.delivery_card')::uuid),'retry nao duplica cupom');
select pg_temp.assert((select (payload->>'bring_card_terminal')::boolean and payload->>'card_fee_cents'='66' and payload#>>'{contact,reference}'='Ao lado da farmacia' from app_private.online_print_jobs where order_id=current_setting('test.delivery_card')::uuid),'cupom inclui maquineta, taxa e referencia');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","session_id":"delivery-test"}',true);
select set_config('test.print_token',public.online_register_printer('Impressora teste','Cadastro para teste controlado')->>'token',true);
select public.online_kitchen_work(current_setting('test.delivery_card')::uuid,'grill',1,'preparing');
select public.online_kitchen_work(current_setting('test.delivery_card')::uuid,'grill',1,'ready');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000002","session_id":"delivery-test"}',true);
select set_config('test.delivery_shift',public.open_shift(0)::text,true);
select public.online_claim_order(current_setting('test.delivery_card')::uuid);
select public.online_fulfill(current_setting('test.delivery_card')::uuid,'dispatched');
do $$begin
 begin perform public.online_fulfill(current_setting('test.delivery_card')::uuid,'completed');raise exception 'ASSERT: concluiu sem receber';exception when raise_exception then if sqlerrm<>'delivery_or_payment_not_ready' then raise;end if;end;
 begin perform public.online_register_printer('Ataque','Tentativa de caixa cadastrar agente');raise exception 'ASSERT: caixa cadastrou impressora';exception when insufficient_privilege then null;end;
end $$;
select public.online_collect_delivery_card(current_setting('test.delivery_card')::uuid,'e4000000-0000-0000-0000-000000000001','NSU-TEST-0001','Transacao conferida e aprovada na maquineta');
select public.online_collect_delivery_card(current_setting('test.delivery_card')::uuid,'e4000000-0000-0000-0000-000000000001','NSU-TEST-0001','Transacao conferida e aprovada na maquineta');
select pg_temp.assert((public.cash_summary(current_setting('test.delivery_shift')::uuid)->>'expected_cents')::int=0,'cartao presencial nao aumenta gaveta de dinheiro');
select public.online_fulfill(current_setting('test.delivery_card')::uuid,'completed');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert((public.online_order_status(repeat('4',64))->>'paid_cents')::int=1166,'conferencia idempotente recebe total com taxa uma vez');
select pg_temp.assert(public.online_order_status(repeat('4',64))->>'status'='completed','cliente acompanha conclusao real');
select set_config('test.print_job',public.online_print_claim(current_setting('test.print_token'))::text,true);
select public.online_print_finish(current_setting('test.print_token'),(current_setting('test.print_job')::jsonb->>'id')::uuid,(current_setting('test.print_job')::jsonb->>'claim')::uuid,true);
select public.online_print_finish(current_setting('test.print_token'),(current_setting('test.print_job')::jsonb->>'id')::uuid,(current_setting('test.print_job')::jsonb->>'claim')::uuid,true);
select pg_temp.assert(public.online_print_claim(current_setting('test.print_token')) is null,'ack repetido nao reimprime');
select set_config('test.delivery_pix',(public.online_create_order('e3000000-0000-0000-0000-000000000002',repeat('5',64),current_setting('test.delivery_items')::jsonb,current_setting('test.delivery_contact')::jsonb,'delivery','pix',null,1100)->>'id'),true);
select public.online_prepare_payment(repeat('5',64),'e4000000-0000-0000-0000-000000000002');
select pg_temp.assert(public.online_order_status(repeat('5',64))->>'status'='accepted' and public.online_order_status(repeat('5',64))->>'paid_cents'='0','Pix pendente fica separado do preparo');
select set_config('test.lost_job',public.online_print_claim(current_setting('test.print_token'))::text,true);
reset role;
update app_private.online_print_jobs set lease_until=now()-interval '1 minute' where id=(current_setting('test.lost_job')::jsonb->>'id')::uuid;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select pg_temp.assert(public.online_print_claim(current_setting('test.print_token')) is null,'falha ambigua nao repete cupom automaticamente');
reset role;
select pg_temp.assert((select status='uncertain' from app_private.online_print_jobs where id=(current_setting('test.lost_job')::jsonb->>'id')::uuid),'falha fica visivel para conferencia');
select pg_temp.assert(exists(select 1 from public.online_notifications where order_id=current_setting('test.delivery_pix')::uuid and topic='order.payment_requested'),'Pix inicial entra na fila WhatsApp');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","session_id":"delivery-test"}',true);
select public.online_retry_print((current_setting('test.lost_job')::jsonb->>'id')::uuid,'Impressora conferida sem papel impresso');
select pg_temp.assert(position(current_setting('test.print_token') in public.online_print_monitor()::text)=0,'monitor nao revela credencial');
reset role;
select pg_temp.assert((select payload->>'reprint'='true' and status='pending' from app_private.online_print_jobs where id=(current_setting('test.lost_job')::jsonb->>'id')::uuid),'segunda via exige acao explicita e e identificada');
rollback;
\o
\echo 'Delivery checkout, accounting, tracking and printer queue tests passed.'
